// W4 app PR B (C5/C9, C1/C12, C6/C14): the pure halves of the bracket read - engine rounds, the drawn roster and the feed
// inversion. No database. The expected values are the ENGINE's own: each bracket is generated by the engine's generator
// and the stored shape by the app's `generate`, and the app's inverse must give back the engine's round for every line.
import { describe, expect, it } from "vitest";
import { generateDoubleElim, generatePagePlayoff, generateSingleElim, generateStepladder } from "@seazn/engine/scheduling";
import { generate } from "@/server/usecases/stages/generators";
import { parseExtKey } from "../competition";
import { attachFeedRefs, engineRoundOf, laneDepthOf, type BracketLane } from "../bracket-rounds";
import { bracketRosterOf, drawSeedsOf } from "../bracket-roster";

const ids = (n: number) => Array.from({ length: n }, (_, i) => `e${i + 1}`);
const active = (n: number) => ids(n).map((id, i) => ({ id, seed: i + 1, swiss_first_round: null }));

interface Case {
  label: string;
  kind: "knockout" | "double_elim" | "page_playoff" | "stepladder";
  cfg: Record<string, unknown>;
  n: number;
  engine: ReadonlyMap<string, number>;
}
function cases(): Case[] {
  const out: Case[] = [];
  const roundsOf = (fixtures: readonly { id: string; round: number }[]) => new Map(fixtures.map((f) => [f.id, f.round] as const));
  for (const n of [2, 3, 4, 5, 8, 11]) {
    const seeds = new Map(ids(n).map((id, i) => [id, i + 1] as const));
    out.push({ label: `knockout ${n}`, kind: "knockout", cfg: {}, n, engine: roundsOf(generateSingleElim({ entrants: ids(n), seeds }).fixtures) });
    if (n >= 4) {
      out.push({ label: `knockout ${n} + third place`, kind: "knockout", cfg: { thirdPlace: true }, n, engine: roundsOf(generateSingleElim({ entrants: ids(n), seeds, thirdPlace: true }).fixtures) });
      out.push({ label: `double_elim ${n}`, kind: "double_elim", cfg: {}, n, engine: roundsOf(generateDoubleElim({ entrants: ids(n), seeds }).fixtures) });
      out.push({ label: `double_elim ${n} + reset`, kind: "double_elim", cfg: { bracketReset: true }, n, engine: roundsOf(generateDoubleElim({ entrants: ids(n), seeds, bracketReset: true }).fixtures) });
      out.push({ label: `page_playoff ${n}`, kind: "page_playoff", cfg: {}, n, engine: roundsOf(generatePagePlayoff({ entrants: ids(4), seeds }).fixtures) });
    }
    out.push({ label: `stepladder ${n}`, kind: "stepladder", cfg: {}, n, engine: roundsOf(generateStepladder({ entrants: ids(n), seeds }).fixtures) });
  }
  return out;
}

describe("engineRoundOf inverts the stored round_no to the engine's own round, on every lane (C5/C9)", () => {
  let checked = 0;
  const lanesSeen = new Set<BracketLane>();
  for (const c of cases()) {
    it(c.label, () => {
      const n = c.kind === "page_playoff" ? 4 : c.n;
      const gen = generate(c.kind, c.cfg, active(n), new Map());
      const depth = laneDepthOf(gen.map((g) => ({ lane: parseExtKey(g.extKey).bracket, roundNo: g.roundNo })));
      expect(gen.length, "premise: the app generated fixtures").toBeGreaterThan(0);
      expect(gen.length, "premise: the same lines as the engine's own generator").toBe(c.engine.size);
      for (const g of gen) {
        const lane = parseExtKey(g.extKey).bracket;
        expect(engineRoundOf(g.roundNo, lane, depth), `${g.extKey} (stored round ${g.roundNo})`).toBe(c.engine.get(g.extKey));
        lanesSeen.add(lane);
        checked++;
      }
    });
  }
  it("anti-vacuity: lines were checked, on all three lanes of a double elimination", () => {
    expect(checked).toBeGreaterThan(100);
    expect(lanesSeen.has("WB") && lanesSeen.has("LB") && lanesSeen.has("GF")).toBe(true);
  });
  it("the opening round of a lane is 0 (what firstLossField needs)", () => {
    expect(engineRoundOf(1, "WB", 3)).toBe(0);
    expect(engineRoundOf(4, "LB", 3)).toBe(0);
    expect(engineRoundOf(7, "GF", 3)).toBe(0);
    expect(engineRoundOf(1, undefined, 0)).toBe(0);
  });
  it("laneDepthOf: no winners' row is depth 0 (the empty case)", () => {
    expect(laneDepthOf([])).toBe(0);
    expect(laneDepthOf([{ lane: "LB", roundNo: 5 }])).toBe(0);
  });
});

describe("bracketRosterOf declares the drawn roster: draw order, then every seat-holder, never a waiting entrant (C1/C12)", () => {
  it("the empty case: nobody drawn, nobody seated", () => {
    expect(bracketRosterOf({ drawn: [], seated: [] })).toEqual([]);
    expect(drawSeedsOf([]).size).toBe(0);
  });
  it("a qualified list keeps its order and a departed qualifier who holds no seat stays on it", () => {
    expect(bracketRosterOf({ drawn: ["q3", "q1", "q2"], seated: ["q1", "q2"] })).toEqual(["q3", "q1", "q2"]);
  });
  it("a seat-holder who was not drawn (a lucky loser) follows; nobody is repeated", () => {
    expect(bracketRosterOf({ drawn: ["a", "b"], seated: ["b", "ll", "a", "ll"] })).toEqual(["a", "b", "ll"]);
  });
  it("a waiting entrant is NOT declared, even if a list names her", () => {
    expect(bracketRosterOf({ drawn: ["a", "w"], seated: ["a", "b"], waiting: new Set(["w", "b"]) })).toEqual(["a"]);
  });
  it("the draw seeds are the position in the drawn order, not a registration seed", () => {
    expect([...drawSeedsOf(["z", "a", "m"])]).toEqual([["z", 1], ["a", 2], ["m", 3]]);
  });
});

describe("attachFeedRefs inverts the forward edges into homeFrom / awayFrom (C6/C14)", () => {
  it("slot 1 is the home seat, slot 2 the away seat, winner and loser edges both, and it counts what it attached", () => {
    const rows = new Map([["sf1", { id: "sf1" }], ["sf2", { id: "sf2" }], ["fin", { id: "fin" } as { id: string; homeFrom?: never }], ["3p", { id: "3p" }]] as const) as Map<string, { id: string; homeFrom?: { fixtureId: string; side: "winner" | "loser" }; awayFrom?: { fixtureId: string; side: "winner" | "loser" } }>;
    const n = attachFeedRefs(rows, [
      { id: "sf1", winner_to_fixture: "fin", winner_to_slot: 1, loser_to_fixture: "3p", loser_to_slot: 1 },
      { id: "sf2", winner_to_fixture: "fin", winner_to_slot: 2, loser_to_fixture: "3p", loser_to_slot: 2 },
      { id: "fin", winner_to_fixture: null, winner_to_slot: null, loser_to_fixture: null, loser_to_slot: null },
    ]);
    expect(n).toBe(4);
    expect(rows.get("fin")).toMatchObject({ homeFrom: { fixtureId: "sf1", side: "winner" }, awayFrom: { fixtureId: "sf2", side: "winner" } });
    expect(rows.get("3p")).toMatchObject({ homeFrom: { fixtureId: "sf1", side: "loser" }, awayFrom: { fixtureId: "sf2", side: "loser" } });
    expect(rows.get("sf1")).toEqual({ id: "sf1" });
  });
  it("no edges attaches nothing, and an edge to a fixture outside the stage or with no slot is skipped", () => {
    const rows = new Map([["a", { id: "a" }]]);
    expect(attachFeedRefs(rows, [])).toBe(0);
    expect(attachFeedRefs(rows, [{ id: "x", winner_to_fixture: "gone", winner_to_slot: 1, loser_to_fixture: "a", loser_to_slot: null }])).toBe(0);
  });
});
